; Hires portrait animation test player (ACME).
; Plays the frames listed in demo_frames.asm (generated by build_demo.sh) in a loop.
; Bitmap $2000, screen RAM $0400. The 15x25-cell strip is drawn at column COL.

!cpu 6510

COL       = 12
FRAMEWAIT = 2           ; extra vblanks per frame (copy itself takes ~3) -> ~10 fps on PAL

src       = $fb         ; 2 bytes
dst       = $fd         ; 2 bytes
rows      = $02
frame     = $03

* = $0801
!byte $0c,$08,$0a,$00,$9e,$32,$30,$36,$31,$00,$00,$00   ; 10 SYS2061

start:
        sei
        lda #$36        ; BASIC ROM off so frame data under $a000 is readable
        sta $01
        lda #0
        sta $d020
        sta $d021

        ; clear bitmap $2000-$3fff and screen $0400-$07ff
        lda #$20
        sta dst+1
        ldx #$20
        lda #0
        sta dst
        tay
-       sta (dst),y
        iny
        bne -
        inc dst+1
        dex
        bne -
        ldx #0
-       sta $0400,x
        sta $0500,x
        sta $0600,x
        sta $0700,x
        inx
        bne -

        lda #$3b        ; bitmap mode, screen on, 25 rows
        sta $d011
        lda #$08        ; hires, 40 columns
        sta $d016
        lda #$18        ; screen $0400, bitmap $2000
        sta $d018

        lda #0
        sta frame
play:
        ldx frame
        lda frames_lo,x
        sta src
        lda frames_hi,x
        sta src+1

        ; bitmap: 25 rows x 120 bytes, destination stride 320
        lda #<($2000 + COL*8)
        sta dst
        lda #>($2000 + COL*8)
        sta dst+1
        lda #25
        sta rows
--      ldy #0
-       lda (src),y
        sta (dst),y
        iny
        cpy #120
        bne -
        lda src
        clc
        adc #120
        sta src
        bcc +
        inc src+1
+       lda dst
        clc
        adc #<320
        sta dst
        lda dst+1
        adc #>320
        sta dst+1
        dec rows
        bne --

        ; screen RAM: 25 rows x 15 bytes, destination stride 40
        lda #<($0400 + COL)
        sta dst
        lda #>($0400 + COL)
        sta dst+1
        lda #25
        sta rows
--      ldy #0
-       lda (src),y
        sta (dst),y
        iny
        cpy #15
        bne -
        lda src
        clc
        adc #15
        sta src
        bcc +
        inc src+1
+       lda dst
        clc
        adc #40
        sta dst
        bcc +
        inc dst+1
+       dec rows
        bne --

        ldx #FRAMEWAIT
-       lda $d012
        cmp #$f8
        bne -
--      lda $d012
        cmp #$f8
        beq --
        dex
        bne -

        inc frame
        lda frame
        cmp #FRAME_COUNT
        bne +
        lda #0
        sta frame
+       jmp play

!source "demo_frames.asm"
!if * > $d000 { !error "too many frames: data runs into I/O at $d000 (10 frames max)" }
